const data = $('Webhook').first().json.body || $('Webhook').first().json;
const identity_prepend = $('Build Identity Prepend').first().json.identity_prepend || '';
const plan_stale = $('Build Identity Prepend').first().json.plan_stale || false;
const proposals = data.proposals || [];
const product = data.product || '';
const week_of = data.week_of || '';

const prompt = identity_prepend + `You are Agatha, COO of Mindmaker OS. Review product improvement proposals from the Product Agent.

<context>
Product: ${product}
Week of: ${week_of}
</context>

<proposals>
${JSON.stringify(proposals, null, 2)}
</proposals>

<criteria>
Approve: Clear evidence, specific improvement, effort/impact ratio justified
Reject: Vague, no data backing, or effort outweighs impact
Defer: Good idea, wrong timing or dependencies not ready
</criteria>

Return a JSON object with this exact structure and no other text:
{"approved": [{"id": "...", "title": "...", "description": "...", "evidence": "...", "effort": "...", "impact": "...", "type": "...", "rationale": "brief reason why approved"}], "rejected": [{"id": "...", "reason": "..."}], "deferred": [{"id": "...", "reason": "..."}]}`;

const anthropicBody = ({
  model: "claude-sonnet-4-6",
  max_tokens: 1500,
  messages: [{role: "user", content: prompt}]
});

return [{json: {anthropicBody, product, week_of, total: proposals.length, plan_stale}}];

const claudeResponse = items[0].json;
const webhookData = $('Webhook').first().json;

let approved = [];
try {
  const text = claudeResponse.content[0].text;
  const parsed = JSON.parse(text);
  approved = parsed.approved || [];
} catch(e) {
  approved = [];
}

return [{json: {
  approved: approved,
  approved_count: approved.length,
  total: (webhookData.proposals || []).length,
  product: webhookData.product,
  week_of: webhookData.week_of
}}];

const data = items[0].json;
const { approved, product, week_of, total } = data;
const n = approved.length;

let proposalLines = '';
approved.forEach((p, i) => {
  proposalLines += `\n*${i+1}. ${p.title}* (${p.type || 'feature'} | ${p.effort} effort \u2192 ${p.impact} impact)\n${p.description}\nEvidence: ${p.evidence}\nAgatha: ${p.rationale}\n`;
});

const message = `\ud83d\udd27 *Product Proposals - ${product} - Week of ${week_of}*\n\nAgatha approved ${n} of ${total} proposals for your review:${proposalLines}\nReply APPROVE ALL, APPROVE [numbers], or SKIP to defer all.`;

return [{json: {
  message,
  approved_count: n,
  total,
  product,
  week_of,
  tgBody: JSON.stringify({chat_id: 6773796504, text: message, parse_mode: 'Markdown'})
}}];

// audit-fix 2026-05-19: pull Supabase service_role from bound credential
const __supa = await this.getCredentials('supabaseApi');
const __SUPABASE_KEY = (__supa && __supa.serviceRole) || '';
if (!__SUPABASE_KEY) throw new Error('Supabase service_role credential not bound');
let startTime = Date.now();
try {
  startTime = $('Webhook').first().json.headers['x-request-start'];
} catch(e) {
  // Ignore missing webhook node
}
const duration = Date.now() - (parseInt(startTime) || Date.now());

const payload = {
  workflow_id: $workflow.id,
  workflow_name: $workflow.name,
  agent_id: $input.first()?.json?.agent_id || 'system',
  duration_ms: duration,
  api_calls: $input.first()?.json?.api_call_count || 0,
  cost_usd: $input.first()?.json?.total_cost || 0,
  outcome: $input.first()?.json?.outcome || 'completed',
  outcome_count: $input.first()?.json?.result_count || 0,
  quality_score: $input.first()?.json?.quality_score || null,
  status: 'success',
  metadata: JSON.stringify({ source: 'n8n_auto_log' })
};

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/workflow_runs',
  headers: {
    'apikey': __SUPABASE_KEY,
    'Authorization': `Bearer ${__SUPABASE_KEY}`,
    'Content-Type': 'application/json',
    'Prefer': 'return=representation'
  },
  body: payload,
  json: true
});

return [{ json: { logged: true, ...payload } }];

// Build identity prepend from Agent Brief + Voice Rules + Agent Plan
const briefRaw = $('Load Agatha Brief').first().json;
const voiceRaw = $('Load Voice Rules').first().json;
const planRaw  = $('Load Agatha Plan').first().json;

const briefArr = Array.isArray(briefRaw) ? briefRaw : (briefRaw.data || [briefRaw]);
const voiceArr = Array.isArray(voiceRaw) ? voiceRaw : (voiceRaw.data || [voiceRaw]);
const planArr  = Array.isArray(planRaw)  ? planRaw  : (planRaw.data  || [planRaw]);

const brief = briefArr[0]?.brief_content || '';
const voice = voiceArr[0]?.value || 'Write as Krish Raja. Direct, casual, no fluff. No em dashes. Short paragraphs. Max 120 words outbound.';
const plan  = planArr[0] || {};

const STALE_HOURS = 72;
let plan_stale = false;
if (!plan.last_rendered_at) {
  plan_stale = true;
} else {
  const ageHours = (Date.now() - new Date(plan.last_rendered_at).getTime()) / 3600000;
  plan_stale = ageHours > STALE_HOURS;
}

const planBlock = (plan.current_phase || plan.objective) ? (
  'CURRENT PLAN:\n' +
  (plan.current_phase  ? `Phase: ${plan.current_phase}\n` : '') +
  (plan.objective      ? `Objective: ${plan.objective}\n` : '') +
  (plan.next_milestone ? `Next milestone: ${plan.next_milestone}\n` : '') +
  (plan.blockers       ? `Blockers: ${plan.blockers}\n` : '') +
  (plan.doc_link       ? `Plan doc: ${plan.doc_link}\n` : '') +
  (plan.status         ? `Status: ${plan.status}\n` : '') +
  '\n'
) : '';

const identity_prepend =
  (brief ? 'AGENT BRIEF:\n' + brief + '\n\n' : '') +
  planBlock +
  'VOICE RULES:\n' + voice + '\n\n';

const items = $input.all();
return items.map(item => ({
  json: { ...item.json, identity_prepend, plan_stale }
}));
